-- Israel deep-dive ES/DE/FR translations (completing 275). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Validación centralizada — sistema de números de asignación SHAAM (solo B2B nacional)', 'Esta página de análisis refleja la orientación pública de la Autoridad Tributaria de Israel y las noticias del sector disponibles en agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El calendario de umbrales ya se ha acelerado una vez y podría volver a cambiar — confirme los requisitos vigentes directamente con la Autoridad Tributaria de Israel (ITA) o con su proveedor de integración antes de basarse en ellos.', 'El mandato israelí se legisló en 2023, pero se desplegó mediante un umbral de facturación decreciente en lugar de oleadas por tamaño de contribuyente: un auténtico piloto sin rechazos desde mayo de 2024 por encima de 25.000 NIS, un control más estricto desde enero de 2025 en 20.000 NIS, y una aceleración anunciada en diciembre de 2025 que comprimió en dos años el despliegue restante de cinco, alcanzando 10.000 NIS en enero de 2026 y el suelo permanente de 5.000 NIS en junio de 2026.', 'Las facturas de SHAAM se envían como JSON estructurado a través de API, o se introducen manualmente mediante el portal web de la ITA — no existe un esquema israelí heredado independiente, ni un paso de elaboración en UBL o XML como en otros mandatos de este seguimiento.', 'El mandato israelí es exclusivamente B2B nacional: se aplica a las facturas entre empresas registradas a efectos del IVA dentro de Israel por encima del umbral vigente. Las operaciones B2C, B2G y transfronterizas (exportación/importación) quedan explícitamente fuera de su alcance — un ámbito más reducido que la mayoría de los mandatos CTC recogidos en este seguimiento.', 'Cumplir implica confirmar si sus volúmenes de facturación superan el umbral vigente, elegir una vía de envío, adaptar sus datos de facturación a los campos exigidos por SHAAM, y prever un procedimiento de contingencia para cuando el sistema o su conexión no estén disponibles.', 'Israel no cuenta con un baremo de multas publicado y cuantificado para el incumplimiento de SHAAM. En su lugar, la aplicación funciona a través del propio sistema del IVA: desde 2025, la ITA puede negarse a emitir un número de asignación para una factura irregular, y sin un número de asignación válido el comprador no puede deducir el IVA soportado — convirtiendo el cumplimiento de la facturación en un requisito previo para la recuperación fiscal en lugar de una infracción sancionada por separado.', 'El sistema de números de asignación SHAAM de Israel se aplica a las facturas B2B nacionales por encima de un umbral decreciente desde que comenzó un auténtico piloto sin rechazos en mayo de 2024. El pleno control y las facultades de rechazo de la ITA se activaron en enero de 2025, y un calendario acelerado anunciado en diciembre de 2025 llevó el umbral hasta su suelo permanente de 5.000 NIS en junio de 2026 — unos 18 meses antes del calendario original previsto para 2028. Las operaciones B2C, B2G y transfronterizas permanecen fuera del alcance del mandato.', '🇮🇱' FROM countries WHERE name_en = 'Israel';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Zentralisiertes Clearing — SHAAM-Zuteilungsnummernsystem (nur inländisches B2B)', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise der israelischen Steuerbehörde und Branchenberichte mit Stand August 2026 wider und dient der allgemeinen Information, nicht der Rechts- oder Steuerberatung. Der Schwellenwertplan wurde bereits einmal beschleunigt und könnte sich erneut ändern — bestätigen Sie aktuelle Anforderungen direkt bei der israelischen Steuerbehörde (ITA) oder Ihrem Integrationsanbieter, bevor Sie darauf aufbauen.', 'Israels Mandat wurde 2023 gesetzlich verankert, aber über eine schrumpfende Rechnungsschwelle statt über Steuerzahlergrößen-Wellen eingeführt: eine echte ablehnungsfreie Pilotphase ab Mai 2024 oberhalb von 25.000 NIS, verschärfte Durchsetzung ab Januar 2025 bei 20.000 NIS, dann eine im Dezember 2025 angekündigte Beschleunigung, die den verbleibenden fünfjährigen Rollout auf zwei Jahre verkürzte und im Januar 2026 10.000 NIS sowie im Juni 2026 die dauerhafte Untergrenze von 5.000 NIS erreichte.', 'SHAAM-Rechnungen werden als strukturiertes JSON per API übermittelt oder manuell über das Webportal der ITA eingegeben — es gibt kein separates israelisches Altschema und keinen UBL- oder XML-Erstellungsschritt wie bei manchen anderen Mandaten in diesem Tracker.', 'Israels Mandat gilt ausschließlich für inländisches B2B: Es betrifft Rechnungen zwischen umsatzsteuerregistrierten Unternehmen innerhalb Israels oberhalb der aktuellen Schwelle. B2C, B2G und grenzüberschreitende Transaktionen (Export/Import) sind ausdrücklich ausgenommen — ein engerer Anwendungsbereich als bei den meisten in diesem Tracker erfassten CTC-Mandaten.', 'Um konform zu sein, müssen Sie prüfen, ob Ihre Rechnungsvolumina die aktuelle Schwelle überschreiten, einen Übermittlungsweg wählen, Ihre Rechnungsdaten auf die von SHAAM geforderten Felder abbilden und ein Notfallverfahren für den Fall aufbauen, dass das System oder Ihre Verbindung nicht verfügbar ist.', 'Israel hat keinen veröffentlichten, bezifferten Bußgeldkatalog für die Nichteinhaltung von SHAAM. Stattdessen erfolgt die Durchsetzung fast ausschließlich über das Mehrwertsteuersystem selbst: Seit 2025 kann die ITA die Ausstellung einer Zuteilungsnummer für eine unregelmäßige Rechnung verweigern, und ohne gültige Zuteilungsnummer kann der Käufer die Vorsteuer nicht abziehen — das macht die Einhaltung der Rechnungsvorschriften zu einer Voraussetzung für die Steuererstattung statt zu einem separat mit Bußgeld belegten Verstoß.', 'Israels SHAAM-Zuteilungsnummernsystem gilt für inländische B2B-Rechnungen oberhalb einer schrumpfenden Schwelle, seit im Mai 2024 eine echte ablehnungsfreie Pilotphase begann. Die volle Prüf- und Ablehnungsbefugnis der ITA wurde im Januar 2025 aktiviert, und ein im Dezember 2025 angekündigter beschleunigter Zeitplan senkte die Schwelle bis Juni 2026 auf ihre dauerhafte Untergrenze von 5.000 NIS — rund 18 Monate früher als im ursprünglichen Zeitplan bis 2028 vorgesehen. B2C-, B2G- und grenzüberschreitende Transaktionen bleiben außerhalb des Anwendungsbereichs des Mandats.', '🇮🇱' FROM countries WHERE name_en = 'Israel';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Validation centralisée — système de numéros d''allocation SHAAM (B2B national uniquement)', 'Cette page d''analyse reflète les directives publiques de l''Autorité fiscale israélienne et les informations sectorielles disponibles en août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Le calendrier des seuils a déjà été accéléré une fois et pourrait encore changer — confirmez les exigences actuelles directement auprès de l''Autorité fiscale israélienne (ITA) ou de votre prestataire d''intégration avant de vous y fier.', 'Le mandat israélien a été légiféré en 2023 mais déployé via un seuil de facturation décroissant plutôt que par vagues selon la taille des contribuables : un véritable pilote sans rejet à partir de mai 2024 au-delà de 25 000 NIS, un contrôle renforcé à partir de janvier 2025 à 20 000 NIS, puis une accélération annoncée en décembre 2025 qui a comprimé en deux ans le déploiement restant sur cinq ans, atteignant 10 000 NIS en janvier 2026 et le plancher permanent de 5 000 NIS en juin 2026.', 'Les factures SHAAM sont soumises sous forme de JSON structuré via API, ou saisies manuellement via le portail web de l''ITA — il n''existe pas de schéma israélien hérité distinct, ni d''étape de rédaction en UBL ou XML comme pour certains autres mandats de ce suivi.', 'Le mandat israélien est exclusivement B2B national : il s''applique aux factures entre entreprises immatriculées à la TVA en Israël au-delà du seuil en vigueur. Les opérations B2C, B2G et transfrontalières (export/import) sont explicitement hors champ — une portée plus restreinte que la plupart des mandats CTC recensés dans ce suivi.', 'Se mettre en conformité implique de vérifier si vos volumes de facturation dépassent le seuil actuel, de choisir une voie de soumission, d''adapter vos données de facturation aux champs requis par SHAAM, et de prévoir une procédure de contingence en cas d''indisponibilité du système ou de votre connexion.', 'Israël ne dispose d''aucun barème d''amendes publié et chiffré pour la non-conformité à SHAAM. L''application passe plutôt presque entièrement par le système de TVA lui-même : depuis 2025, l''ITA peut refuser d''émettre un numéro d''allocation pour une facture jugée irrégulière, et sans numéro d''allocation valide, l''acheteur ne peut pas déduire la TVA en amont — faisant de la conformité de facturation une condition préalable à la récupération fiscale plutôt qu''une infraction sanctionnée séparément.', 'Le système de numéros d''allocation SHAAM d''Israël s''applique aux factures B2B nationales au-delà d''un seuil décroissant depuis le début d''un véritable pilote sans rejet en mai 2024. Le plein pouvoir de contrôle et de refus de l''ITA a été activé en janvier 2025, et un calendrier accéléré annoncé en décembre 2025 a ramené le seuil à son plancher permanent de 5 000 NIS d''ici juin 2026 — environ 18 mois plus tôt que le calendrier initial prévu pour 2028. Les opérations B2C, B2G et transfrontalières restent hors du champ d''application du mandat.', '🇮🇱' FROM countries WHERE name_en = 'Israel';

