INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato de envío", "JSON estructurado a través de API, o introducción manual mediante el portal web de la ITA"], ["Identificador clave", "Número de asignación de 9 dígitos emitido por cada factura validada"], ["Referencia en la declaración de IVA", "Números de asignación reportados en el Formulario PCN874"], ["Base legal", "Ley de Eficiencia Económica (Enmiendas Presupuestarias) 2023-2024, que modifica la Ley del IVA de 1975"]]', 'Aquí no hay un estándar de elaboración de facturas comparable a UBL o Peppol que aprender — el trabajo de integración es casi enteramente la conexión a la API y la adaptación de campos, ya que el formato subyacente es simplemente JSON estructurado.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Übermittlungsformat", "Strukturiertes JSON per API, oder manuelle Eingabe über das ITA-Webportal"], ["Wichtige Kennung", "9-stellige Zuteilungsnummer pro validierter Rechnung"], ["Referenz in der Umsatzsteuererklärung", "Zuteilungsnummern werden im Formular PCN874 gemeldet"], ["Rechtsgrundlage", "Gesetz zur wirtschaftlichen Effizienz (Haushaltsänderungen) 2023-2024, Änderung des Mehrwertsteuergesetzes von 1975"]]', 'Hier gibt es keinen Rechnungserstellungsstandard vergleichbar mit UBL oder Peppol zu lernen — die Integrationsarbeit besteht fast ausschließlich aus der API-Anbindung und der Feldzuordnung, da das zugrunde liegende Format schlicht strukturiertes JSON ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format de soumission", "JSON structuré via API, ou saisie manuelle via le portail web de l''ITA"], ["Identifiant clé", "Numéro d''allocation à 9 chiffres émis par facture validée"], ["Référence sur la déclaration de TVA", "Numéros d''allocation déclarés sur le formulaire PCN874"], ["Base légale", "Loi sur l''efficacité économique (amendements budgétaires) 2023-2024, modifiant la loi sur la TVA de 1975"]]', 'Il n''existe ici aucune norme de rédaction de factures comparable à UBL ou Peppol à apprendre — le travail d''intégration consiste presque entièrement en la connexion API et la correspondance des champs, le format sous-jacent étant simplement du JSON structuré.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Identidad del contribuyente", "Número de registro de IVA israelí"], ["Vías de acceso", "Integración directa por API, o el portal manual gratuito de gov.il"], ["Campo de software acreditado", "Accounting_Software_Number, obligatorio al enviar mediante software contable certificado"], ["Portal de solicitud", "gov.il — solicitud de número de asignación para una factura fiscal"]]', 'El campo Accounting_Software_Number importa específicamente para las empresas que usan software contable acreditado en lugar de una integración a medida — confirme con su proveedor de software si se rellena automáticamente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Steuerzahleridentität", "Israelische Umsatzsteuerregistrierungsnummer"], ["Zugangswege", "Direkte API-Integration oder das kostenlose manuelle gov.il-Portal"], ["Feld für akkreditierte Software", "Accounting_Software_Number, erforderlich bei Übermittlung über zertifizierte Buchhaltungssoftware"], ["Antragsportal", "gov.il — Beantragung einer Zuteilungsnummer für eine Steuerrechnung"]]', 'Das Feld Accounting_Software_Number ist besonders für Unternehmen relevant, die akkreditierte Buchhaltungssoftware statt einer individuellen Integration nutzen — klären Sie mit Ihrem Softwareanbieter, ob es automatisch befüllt wird.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Identité du contribuable", "Numéro d''immatriculation à la TVA israélien"], ["Voies d''accès", "Intégration API directe, ou le portail manuel gratuit gov.il"], ["Champ logiciel accrédité", "Accounting_Software_Number, requis lors d''une soumission via un logiciel comptable certifié"], ["Portail de demande", "gov.il — demande de numéro d''allocation pour une facture fiscale"]]', 'Le champ Accounting_Software_Number concerne particulièrement les entreprises utilisant un logiciel comptable accrédité plutôt qu''une intégration sur mesure — vérifiez auprès de votre éditeur logiciel s''il est renseigné automatiquement.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio y archivo', '[["Detalle de partidas", "No se exige en el envío inicial -- una carga de datos más ligera que la mayoría de los mandatos CTC de este seguimiento"], ["Periodo de conservación", "7 años"], ["Contingencia por caída del sistema", "La Sección 40B permite solicitudes retroactivas de número de asignación cuando SHAAM o los sistemas propios de la empresa no están disponibles"], ["Servicio de verificación", "gov.il -- verificar la información de la factura del proveedor"]]', 'La ausencia de un requisito de envío por partidas es una simplificación real en comparación con mandatos equivalentes -- pero el periodo de conservación de 7 años y el proceso de contingencia de la Sección 40B siguen mereciendo un diseño de proceso real, no una idea de último momento.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalt & Archivierung', '[["Positionsdetails", "Bei der Erstübermittlung nicht erforderlich -- ein leichterer Datenfußabdruck als bei den meisten CTC-Mandaten in diesem Tracker"], ["Aufbewahrungsfrist", "7 Jahre"], ["Ausfall-Kontingenz", "Abschnitt 40B erlaubt rückwirkende Anträge auf Zuteilungsnummern, wenn SHAAM oder die eigenen Systeme des Unternehmens nicht verfügbar sind"], ["Verifizierungsdienst", "gov.il -- Überprüfung der Rechnungsangaben des Lieferanten"]]', 'Das Fehlen einer Positionsdetail-Anforderung ist im Vergleich zu vergleichbaren Mandaten eine echte Vereinfachung -- doch die 7-jährige Aufbewahrungsfrist und der Kontingenzprozess nach Abschnitt 40B verdienen weiterhin echtes Prozessdesign, keinen nachträglichen Einfall.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire et archivage', '[["Détail des lignes", "Non requis dans la soumission initiale -- une empreinte de données plus légère que la plupart des mandats CTC de ce suivi"], ["Durée de conservation", "7 ans"], ["Contingence en cas de panne", "La section 40B permet des demandes rétroactives de numéro d''allocation lorsque SHAAM ou les propres systèmes de l''entreprise sont indisponibles"], ["Service de vérification", "gov.il -- vérifier les informations de facture du fournisseur"]]', 'L''absence d''exigence de soumission ligne par ligne est une réelle simplification par rapport aux mandats comparables -- mais la durée de conservation de 7 ans et le processus de contingence de la section 40B méritent toujours une véritable conception de processus, pas une réflexion après coup.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de validación', 'Toda factura de SHAAM sujeta al mandato pasa por la misma secuencia:', 'El comprador necesita un número de asignación válido en la factura antes de poder deducir el IVA soportado -- esto es lo que hace de SHAAM un verdadero modelo de validación en lugar de un sistema de reporte posterior a la transacción.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Israel' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Clearing-Ablauf', 'Jede in den Anwendungsbereich fallende SHAAM-Rechnung durchläuft dieselbe Sequenz:', 'Der Käufer benötigt eine gültige Zuteilungsnummer auf der Rechnung, bevor er die Vorsteuer abziehen kann -- das macht SHAAM zu einem echten Clearing-Modell statt einem Meldesystem nach der Transaktion.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Israel' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux de validation', 'Chaque facture SHAAM concernée suit la même séquence :', 'L''acheteur a besoin d''un numéro d''allocation valide sur la facture avant de pouvoir déduire la TVA en amont -- c''est ce qui fait de SHAAM un véritable modèle de validation plutôt qu''un système de déclaration après transaction.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Israel' AND lc.sort_order = 0;

