INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'La reducción gradual del umbral', '[["Desde el 5 de mayo de 2024", "Piloto -- por encima de 25.000 NIS, sin rechazos por contenido"], ["Desde el 1 de enero de 2025", "20.000 NIS -- se activan el pleno control y las facultades de rechazo de la ITA"], ["Desde el 1 de enero de 2026", "10.000 NIS -- calendario acelerado, saltando el escalón de 15.000 NIS previsto"], ["Desde el 1 de junio de 2026", "5.000 NIS -- el suelo permanente, sin más reducciones previstas por ahora"]]', 'El despliegue basado en umbrales es un mecanismo genuinamente distinto al de cualquier otro mandato de este seguimiento -- no hay oleadas por tamaño de contribuyente, solo un suelo de valor de factura decreciente que acaba abarcando casi toda la actividad B2B nacional.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Die schrittweise Schwellenabsenkung', '[["Ab 5. Mai 2024", "Pilotphase -- über 25.000 NIS, keine inhaltlichen Ablehnungen"], ["Ab 1. Januar 2025", "20.000 NIS -- volle Prüf- und Ablehnungsbefugnisse der ITA aktiviert"], ["Ab 1. Januar 2026", "10.000 NIS -- beschleunigter Zeitplan, überspringt die geplante Stufe von 15.000 NIS"], ["Ab 1. Juni 2026", "5.000 NIS -- die dauerhafte Untergrenze, derzeit keine weiteren Absenkungen geplant"]]', 'Der schwellenbasierte Rollout ist ein wirklich anderer Mechanismus als bei jedem anderen Mandat in diesem Tracker -- es gibt hier keine Steuerzahlergrößen-Wellen, nur eine schrumpfende Rechnungswert-Untergrenze, die letztlich fast die gesamte inländische B2B-Aktivität erfasst.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'La baisse progressive du seuil', '[["À partir du 5 mai 2024", "Pilote -- au-delà de 25 000 NIS, aucun rejet pour motif de contenu"], ["À partir du 1er janvier 2025", "20 000 NIS -- pleins pouvoirs de contrôle et de refus de l''ITA activés"], ["À partir du 1er janvier 2026", "10 000 NIS -- calendrier accéléré, sautant l''étape de 15 000 NIS prévue"], ["À partir du 1er juin 2026", "5 000 NIS -- le plancher permanent, aucune nouvelle baisse actuellement prévue"]]', 'Le déploiement fondé sur un seuil est un mécanisme véritablement différent de tout autre mandat de ce suivi -- il n''y a pas ici de vagues selon la taille des contribuables, seulement un plancher de valeur de facture décroissant qui finit par couvrir la quasi-totalité de l''activité B2B nationale.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Qué queda explícitamente fuera de alcance', '[["Ventas B2C", "No cubiertas -- las facturas dirigidas a consumidores quedan fuera de SHAAM"], ["Operaciones B2G", "No cubiertas por este mandato"], ["Exportaciones e importaciones", "El comercio transfronterizo queda excluido"], ["B2B por debajo del umbral", "Las facturas B2B nacionales por debajo del umbral vigente en NIS quedan fuera del requisito"]]', 'Vale la pena contrastar este alcance B2B más reducido con su propia combinación de operaciones -- una empresa con ingresos mayoritariamente B2C o de exportación puede tener mucha menos exposición a SHAAM de lo que sugiere el titular "facturación electrónica obligatoria".', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was ausdrücklich außerhalb des Anwendungsbereichs liegt', '[["B2C-Verkäufe", "Nicht erfasst -- verbraucherbezogene Rechnungen bleiben außerhalb von SHAAM"], ["B2G-Transaktionen", "Von diesem Mandat nicht erfasst"], ["Exporte und Importe", "Grenzüberschreitender Handel ist ausgenommen"], ["B2B unterhalb der Schwelle", "Inländische B2B-Rechnungen unterhalb der aktuellen NIS-Schwelle bleiben von der Anforderung ausgenommen"]]', 'Dieser engere B2B-only-Anwendungsbereich lohnt einen Abgleich mit Ihrer eigenen Umsatzmischung -- ein Unternehmen mit überwiegend B2C- oder Exportumsatz kann eine deutlich geringere SHAAM-Betroffenheit haben, als die Schlagzeile "verpflichtende E-Rechnung" nahelegt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce qui est explicitement hors champ', '[["Ventes B2C", "Non couvertes -- les factures destinées aux consommateurs restent hors de SHAAM"], ["Opérations B2G", "Non couvertes par ce mandat"], ["Exportations et importations", "Le commerce transfrontalier est exclu"], ["B2B sous le seuil", "Les factures B2B nationales sous le seuil NIS actuel restent hors de l''obligation"]]', 'Ce champ d''application B2B plus restreint mérite d''être comparé à votre propre mix d''opérations -- une entreprise dont le chiffre d''affaires est majoritairement B2C ou export peut avoir une exposition à SHAAM bien plus faible que ne le suggère le slogan « facturation électronique obligatoire ».', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🧾 Denegación de la deducción del IVA — el verdadero motor de aplicación', NULL, NULL, 'Israel hace cumplir SHAAM casi enteramente a través del sistema del IVA en lugar de multas directas: sin un número de asignación válido, el comprador no puede deducir el IVA soportado de esa factura. Un proveedor que no lo obtenga no se enfrenta directamente a una sanción -- su factura simplemente pierde valor para los clientes registrados a efectos del IVA, lo que impulsa el cumplimiento sin necesidad de un baremo de multas publicado.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🧾 Verweigerung des Vorsteuerabzugs — der eigentliche Durchsetzungsmotor', NULL, NULL, 'Israel setzt SHAAM fast ausschließlich über das Mehrwertsteuersystem durch, nicht über direkte Bußgelder: Ohne gültige Zuteilungsnummer kann der Käufer die Vorsteuer aus dieser Rechnung nicht abziehen. Ein Lieferant, der keine erhält, wird nicht direkt bestraft -- seine Rechnung wird für umsatzsteuerregistrierte Kunden schlicht wertlos, was die Einhaltung ohne veröffentlichten Bußgeldkatalog vorantreibt.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🧾 Refus de déduction de la TVA — le véritable moteur d''application', NULL, NULL, 'Israël fait respecter SHAAM presque entièrement via le système de TVA plutôt que par des amendes directes : sans numéro d''allocation valide, l''acheteur ne peut pas déduire la TVA en amont sur cette facture. Un fournisseur qui n''en obtient pas ne s''expose pas directement à une sanction -- sa facture devient simplement sans valeur pour ses clients assujettis à la TVA, ce qui favorise la conformité sans barème d''amendes publié.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🔍 La ITA ya puede decir que no', NULL, NULL, 'Desde enero de 2025, el periodo de gracia sin rechazos del piloto ha terminado: la ITA puede examinar los envíos y negarse a emitir un número de asignación para una factura que considere irregular, con un proceso formal de revisión y audiencia disponible en un plazo de 2 días hábiles tras un rechazo.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🔍 Die ITA kann jetzt Nein sagen', NULL, NULL, 'Seit Januar 2025 ist die ablehnungsfreie Übergangsfrist der Pilotphase beendet: Die ITA kann Einreichungen prüfen und die Ausstellung einer Zuteilungsnummer für eine als unregelmäßig eingestufte Rechnung verweigern, mit einem formellen Überprüfungs- und Anhörungsverfahren innerhalb von 2 Werktagen nach einer Ablehnung.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🔍 L''ITA peut désormais refuser', NULL, NULL, 'Depuis janvier 2025, la période de grâce sans rejet du pilote a pris fin : l''ITA peut examiner les soumissions et refuser d''émettre un numéro d''allocation pour une facture jugée irrégulière, avec une procédure formelle de révision et d''audience disponible dans un délai de 2 jours ouvrés après un refus.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚠️ Sin baremo de multas publicado', NULL, NULL, 'A diferencia de varios mandatos de este seguimiento, ninguna fuente revisada aquí documenta un baremo de multas fijas y cuantificadas para el incumplimiento de SHAAM -- el mecanismo de deducción del IVA descrito arriba parece ser la principal palanca de aplicación. Confirme directamente con la ITA si se introduce una estructura sancionadora formal.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚠️ Kein veröffentlichter Bußgeldkatalog', NULL, NULL, 'Anders als bei mehreren Mandaten in diesem Tracker dokumentiert keine hier geprüfte Quelle einen bezifferten festen Bußgeldkatalog für die Nichteinhaltung von SHAAM -- der oben beschriebene Vorsteuerabzugsmechanismus scheint der primäre Durchsetzungshebel zu sein. Bestätigen Sie direkt bei der ITA, falls eine formelle Bußgeldstruktur eingeführt wird.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚠️ Aucun barème d''amendes publié', NULL, NULL, 'Contrairement à plusieurs mandats de ce suivi, aucune source examinée ici ne documente de barème d''amendes fixes et chiffrées pour la non-conformité à SHAAM -- le mécanisme de déduction de la TVA décrit ci-dessus semble être le principal levier d''application. Confirmez directement auprès de l''ITA si une structure de sanctions formelle est introduite.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Israel' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme si el umbral vigente le afecta', 'Compare el valor habitual de sus facturas B2B nacionales con el suelo actual de 5.000 NIS -- recuerde que las facturas B2C, B2G y transfronterizas quedan fuera de alcance sin importar su valor.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie, ob die aktuelle Schwelle für Sie gilt', 'Vergleichen Sie Ihre üblichen inländischen B2B-Rechnungswerte mit der aktuellen Untergrenze von 5.000 NIS -- denken Sie daran, dass B2C-, B2G- und grenzüberschreitende Rechnungen unabhängig vom Wert außerhalb des Anwendungsbereichs bleiben.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez si le seuil actuel vous concerne', 'Comparez la valeur habituelle de vos factures B2B nationales au plancher actuel de 5 000 NIS -- rappelez-vous que les factures B2C, B2G et transfrontalières restent hors champ quelle que soit leur valeur.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija su vía de envío', 'Las empresas de mayor volumen deberían integrarse directamente a través de la API de SHAAM; el portal manual gratuito de gov.il conviene a quienes envían con menor volumen y sin recursos de desarrollo propios.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihren Übermittlungsweg', 'Unternehmen mit höherem Volumen sollten direkt über die SHAAM-API integrieren; das kostenlose manuelle gov.il-Portal eignet sich für Einreicher mit geringerem Volumen ohne eigene Entwicklungsressourcen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez votre voie de soumission', 'Les entreprises à volume plus élevé devraient s''intégrer directement via l''API SHAAM ; le portail manuel gratuit gov.il convient aux soumissionnaires à faible volume sans ressources de développement internes.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Adapte sus datos de facturación a los campos JSON exigidos', 'El detalle de partidas no se exige en el envío inicial, lo que simplifica la adaptación frente a mandatos equivalentes -- pero los campos de identidad del contribuyente y valor de la factura siguen debiendo ser precisos.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bilden Sie Ihre Rechnungsdaten auf die erforderlichen JSON-Felder ab', 'Positionsdetails sind bei der Erstübermittlung nicht erforderlich, was die Zuordnung gegenüber vergleichbaren Mandaten vereinfacht -- doch die Felder für Steuerzahleridentität und Rechnungswert müssen weiterhin korrekt sein.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Adaptez vos données de facturation aux champs JSON requis', 'Le détail des lignes n''est pas requis dans la soumission initiale, ce qui simplifie la correspondance par rapport aux mandats comparables -- mais les champs d''identité du contribuable et de valeur de facture doivent rester exacts.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Rellene el campo Accounting_Software_Number si corresponde', 'Si envía a través de software contable acreditado en lugar de una integración a medida, confirme que este campo se rellena correctamente -- consúltelo con su proveedor de software en lugar de darlo por hecho.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Füllen Sie das Feld Accounting_Software_Number aus, falls zutreffend', 'Wenn Sie über akkreditierte Buchhaltungssoftware statt einer individuellen Integration übermitteln, bestätigen Sie, dass dieses Feld korrekt befüllt wird -- fragen Sie bei Ihrem Softwareanbieter nach, statt es anzunehmen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Renseignez le champ Accounting_Software_Number le cas échéant', 'Si vous soumettez via un logiciel comptable accrédité plutôt qu''une intégration sur mesure, vérifiez que ce champ est correctement renseigné -- consultez votre éditeur logiciel plutôt que de le supposer.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elabore un proceso de contingencia para caídas del sistema', 'La Sección 40B permite solicitudes retroactivas de número de asignación cuando SHAAM o sus propios sistemas no están disponibles -- diseñe este procedimiento de antemano en lugar de improvisar durante una interrupción.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Entwickeln Sie ein Kontingenzverfahren für Systemausfälle', 'Abschnitt 40B erlaubt rückwirkende Anträge auf Zuteilungsnummern, wenn SHAAM oder Ihre eigenen Systeme nicht verfügbar sind -- planen Sie dieses Vorgehen im Voraus, statt es während eines Ausfalls zu improvisieren.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Élaborez un processus de contingence en cas de panne du système', 'La section 40B permet des demandes rétroactives de numéro d''allocation lorsque SHAAM ou vos propres systèmes sont indisponibles -- concevez ce traitement à l''avance plutôt que de l''improviser pendant une panne.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Reporte los números de asignación en el Formulario PCN874', 'Confirme que su proceso de declaración de IVA referencia correctamente los números de asignación -- una factura sin uno no es solo un riesgo de cumplimiento, bloquea la deducción del IVA soportado de su cliente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Melden Sie Zuteilungsnummern im Formular PCN874', 'Bestätigen Sie, dass Ihr Umsatzsteuererklärungsprozess die Zuteilungsnummern korrekt referenziert -- eine Rechnung ohne eine solche ist nicht nur ein Compliance-Risiko, sie blockiert den Vorsteuerabzug Ihres Kunden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Déclarez les numéros d''allocation sur le formulaire PCN874', 'Vérifiez que votre processus de déclaration de TVA référence correctement les numéros d''allocation -- une facture qui en est dépourvue n''est pas seulement un risque de conformité, elle bloque la déduction de la TVA en amont de votre client.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Israel' AND ds.sort_order = 5;

